import pandas as pd

def find_subtasks(tasks: pd.DataFrame, executed: pd.DataFrame) -> pd.DataFrame:
    rows = []
    for _, row in tasks.iterrows():
        for sid in range(1, row["subtasks_count"] + 1):
            rows.append({"task_id": row["task_id"], "subtask_id": sid})
    all_subtasks = pd.DataFrame(rows)
    if all_subtasks.empty:
        return pd.DataFrame(columns=["task_id", "subtask_id"])
    merged = all_subtasks.merge(executed, on=["task_id", "subtask_id"], how="left", indicator=True)
    return merged[merged["_merge"] == "left_only"][["task_id", "subtask_id"]]
